import React, { forwardRef, Children } from "react";
import { clsx } from "clsx";
import { IconButton } from "@components/icon-button";
import { Filter as FilterIcon } from "@exp-textura/icons";
import { Float } from "@components/float";

import { ListClasses } from "../list.styles";
import { ListFilterIconButtonProps } from "../list.types";

export const ListFilterIconButton = forwardRef(
  (
    { floatProps, className, children, ...props }: ListFilterIconButtonProps,
    ref: React.ForwardedRef<HTMLButtonElement>,
  ) => {
    const childrenArray = Children.toArray(children);

    const badge = childrenArray.find(
      (child) =>
        React.isValidElement(child) &&
        (child.type as React.FunctionComponent).displayName === "List.FilterIconButtonBadge",
    );

    const otherChildren = childrenArray.filter((child) => child !== badge);

    return (
      <Float offSetX={4} offSetY={4} placement="top-end" {...floatProps}>
        {badge && <Float.Content>{badge}</Float.Content>}
        <Float.Anchor>
          <IconButton
            ref={ref}
            buttonType="secondary"
            {...props}
            className={clsx(ListClasses.filterIconButton, className)}
          >
            {otherChildren.length > 0 ? otherChildren : <FilterIcon />}
          </IconButton>
        </Float.Anchor>
      </Float>
    );
  },
);

ListFilterIconButton.displayName = "List.FilterIconButton";
